read Q;read T;read K||K=x;python3 -c 'import sys,json as j,re;q,T,k=sys.argv[1:];J=lambda x:j.dumps(x,separators=(",",":"));w=re.findall(r"\w+",q.lower())or["merry","christmas"];k="".join(c for c in k if c.isalnum())or"x";Q="I P B U G Z C O".split();d=[[Q[i],Q[i+1]]for i in range(7)];O=["B=N*","A=actual","K=minZ"];TM=[Q,d,O];g=sum((x+1)*257**i for i,x in enumerate(J([TM,w,k,T]).encode()));t=int(T)if T else 4*len(w)+24;M=997+g%997;Y=[((g+i*i+3*i)%M,i)for i in range((2<<min(t,10))-1)];b=list(min(Y));a=(-g-b[1])%M;Z=[M,a,(g+b[1]+a)%M];tr=[[Q[min(i,7)],i%2]for i in range(len(Q))];C=[["O",O],["B",["N*",len(Y),b]],["TM",TM],["TR",tr],["G",str(g+b[1])],["Z",Z],["R","1/2+i*log(1+G)"],["H"]];v=int(j.loads(J(C))==C and Z[2]==0);D={"P":"RMZ-XMAS-OB-FORMAL-2K","D":"B=N*","NL":" ".join(w),"O":O,"B":["N*",len(Y),b],"M":TM,"TR":tr,"G":str(g+b[1]),"RHO":"1/2+i*log(1+G)","ZP":Z,"BUG":1-v,"PCC":v,"ZE":v};open("Merry_Christmas.clcert","w").write(J(D)+"\n");print(J(D))' "$Q" "$T" "$K"
